"""Deterministic input routes and EWRAM-diff capture for starter calibration.

This module is deliberately controller-owned.  It is a measurement tool used
to establish a ROM-specific starter map; it is never exposed to Jev.
"""

from __future__ import annotations

import argparse
import json
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Protocol, Sequence

import numpy as np

from pyboy_adapter import GbaKey, PyBoyAdvance
from qualification import EWRAM_START, visual_fingerprint


EWRAM_SIZE = 256 * 1024
MAX_STEP_FRAMES = 600
MAX_ROUTE_FRAMES = 30_000


class RouteAdapter(Protocol):
    frame_count: int

    def frame(self, count: int = 1) -> None: ...

    def tap(self, key: GbaKey, hold_frames: int = 1, settle_frames: int = 1) -> None: ...

    def pixels(self) -> np.ndarray: ...

    def peek_u8(self, address: int) -> int: ...


@dataclass(frozen=True)
class RouteStep:
    """One named, bounded controller action in a calibration route."""

    name: str
    key: GbaKey | None
    frames: int
    hold_frames: int = 2

    def __post_init__(self) -> None:
        if not self.name:
            raise ValueError("route step name must not be empty")
        if (
            isinstance(self.frames, bool)
            or not isinstance(self.frames, int)
            or not 0 <= self.frames <= MAX_STEP_FRAMES
        ):
            raise ValueError(
                f"route step frames must be between 0 and {MAX_STEP_FRAMES}"
            )
        if isinstance(self.hold_frames, bool) or not isinstance(self.hold_frames, int):
            raise ValueError("route step hold_frames must be an integer")
        if self.key is None and self.hold_frames != 2:
            raise ValueError("wait steps must use the default hold_frames")
        if self.key is not None and self.hold_frames <= 0:
            raise ValueError("input steps require at least one hold frame")
        if self.frame_cost > MAX_STEP_FRAMES:
            raise ValueError(
                f"route step frame cost must not exceed {MAX_STEP_FRAMES}"
            )

    @property
    def frame_cost(self) -> int:
        """Actual emulator frames consumed by this step."""

        return self.frames + (self.hold_frames if self.key is not None else 0)


@dataclass(frozen=True)
class RouteCheckpoint:
    """Visible evidence after one route step."""

    name: str
    frame_count: int
    framebuffer_sha256: str


@dataclass(frozen=True)
class RamDifference:
    """One EWRAM byte changed by a deliberately measured input."""

    address: int
    before: int
    after: int


def run_route(adapter: RouteAdapter, steps: Sequence[RouteStep]) -> tuple[RouteCheckpoint, ...]:
    """Execute a named route and capture a visible checkpoint after each step."""

    validate_route(steps)
    checkpoints: list[RouteCheckpoint] = []
    for step in steps:
        if step.key is None:
            adapter.frame(step.frames)
        else:
            adapter.tap(step.key, hold_frames=step.hold_frames, settle_frames=step.frames)
        pixels = adapter.pixels()
        checkpoints.append(
            RouteCheckpoint(
                name=step.name,
                frame_count=adapter.frame_count,
                framebuffer_sha256=str(visual_fingerprint(pixels)["sha256"]),
            )
        )
    return tuple(checkpoints)


def validate_route(steps: Sequence[RouteStep]) -> None:
    """Reject empty or over-budget routes before they advance the emulator."""

    if not steps:
        raise ValueError("route must contain at least one step")
    total_frames = sum(step.frame_cost for step in steps)
    if total_frames > MAX_ROUTE_FRAMES:
        raise ValueError(
            f"route frame budget exceeded: {total_frames} > {MAX_ROUTE_FRAMES}"
        )


def snapshot_ewram(adapter: RouteAdapter) -> bytes:
    """Capture the complete public EWRAM telemetry surface without advancing time."""

    return bytes(adapter.peek_u8(EWRAM_START + offset) for offset in range(EWRAM_SIZE))


def diff_ewram(before: bytes, after: bytes) -> tuple[RamDifference, ...]:
    """Return every changed EWRAM byte; unequal snapshot sizes are invalid evidence."""

    if len(before) != EWRAM_SIZE or len(after) != EWRAM_SIZE:
        raise ValueError(f"EWRAM snapshots must each be {EWRAM_SIZE} bytes")
    return tuple(
        RamDifference(EWRAM_START + offset, old, new)
        for offset, (old, new) in enumerate(zip(before, after))
        if old != new
    )


def load_route(path: Path) -> tuple[RouteStep, ...]:
    """Load a checked calibration route from JSON, rejecting arbitrary key values."""

    try:
        data = json.loads(path.read_text())
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"cannot read route JSON {path}: {exc}") from exc
    if not isinstance(data, list) or not data:
        raise ValueError("route JSON must be a non-empty list")
    steps: list[RouteStep] = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("each route step must be an object")
        key_name = item.get("key")
        try:
            key = None if key_name is None else GbaKey[str(key_name)]
        except KeyError as exc:
            raise ValueError(f"unknown GBA key in route: {key_name!r}") from exc
        steps.append(
            RouteStep(
                name=str(item.get("name", "")),
                key=key,
                frames=item.get("frames"),
                hold_frames=item.get("hold_frames", 2),
            )
        )
    route = tuple(steps)
    validate_route(route)
    return route


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--rom", type=Path, required=True)
    parser.add_argument("--bios", type=Path, required=True)
    parser.add_argument("--route", type=Path, required=True)
    parser.add_argument("--diff-step", required=True)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        steps = load_route(args.route)
        names = [step.name for step in steps]
        if names.count(args.diff_step) != 1:
            raise ValueError("--diff-step must name exactly one route step")
        adapter = PyBoyAdvance(args.rom, args.bios, skip_bios=False, emulation_speed=0)
        before: bytes | None = None
        after: bytes | None = None
        checkpoints: list[RouteCheckpoint] = []
        for step in steps:
            if step.name == args.diff_step:
                before = snapshot_ewram(adapter)
            checkpoints.extend(run_route(adapter, (step,)))
            if step.name == args.diff_step:
                after = snapshot_ewram(adapter)
        assert before is not None and after is not None
        print(
            json.dumps(
                {
                    "checkpoints": [asdict(item) for item in checkpoints],
                    "diff_step": args.diff_step,
                    "ewram_diff": [asdict(item) for item in diff_ewram(before, after)],
                },
                sort_keys=True,
            )
        )
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        print(json.dumps({"error": str(exc)}, sort_keys=True))
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"""Small, headless adapter for the PyBoy Advance emulator.

The adapter deliberately exposes controller input and read-only telemetry.  It
does not expose the backend object or any memory-writing operation to callers.
"""

from __future__ import annotations

from pathlib import Path
from enum import Enum, auto
from typing import Any

import numpy as np


class BackendCapabilityError(RuntimeError):
    """Raised when the installed backend cannot support a requested phase."""


class PyBoyAdvance:
    """Own a PyBoy Advance instance and expose safe episode primitives."""

    FRAME_WIDTH = 240
    FRAME_HEIGHT = 160

    def __init__(
        self,
        rom: str | Path,
        bios: str | Path,
        skip_bios: bool = False,
        emulation_speed: float = 0,
    ) -> None:
        try:
            from pyboy_advance import PyBoyAdvance as BackendPyBoyAdvance
        except ImportError as exc:  # pragma: no cover - depends on environment
            raise RuntimeError(
                "PyBoy Advance is not installed; install requirements.txt first"
            ) from exc

        self._emulator: Any = BackendPyBoyAdvance(
            rom=rom,
            bios=bios,
            skip_bios=skip_bios,
            emulation_speed=emulation_speed,
        )
        self._rom = rom
        self._bios = bios
        self._skip_bios = skip_bios
        self._emulation_speed = emulation_speed
        self._frame_count = 0

    @property
    def frame_count(self) -> int:
        """Number of frames requested through this adapter."""

        return self._frame_count

    def timing_checkpoint(self) -> int:
        """Read the backend's public, non-mutating emulation cycle counter."""

        reader = getattr(self._emulator, "timing_checkpoint", None)
        if not callable(reader):
            raise BackendCapabilityError(
                "installed PyBoy backend does not expose timing_checkpoint; "
                "install the SHA-pinned fork"
            )
        value = reader()
        if isinstance(value, bool) or not isinstance(value, int):
            raise BackendCapabilityError("backend timing_checkpoint did not return an integer")
        return value

    def frame(self, count: int = 1) -> None:
        """Advance exactly ``count`` frames and update the adapter counter."""

        if isinstance(count, bool) or not isinstance(count, int):
            raise TypeError("frame count must be an integer")
        if count < 0:
            raise ValueError("frame count must be non-negative")
        self._emulator.frame(count)
        self._frame_count += count

    def pixels(self) -> np.ndarray:
        """Return a detached RGB framebuffer with shape ``(160, 240, 3)``."""

        pixels = np.asarray(self._emulator.screen.ndarray, dtype=np.uint8)
        expected_shape = (self.FRAME_HEIGHT, self.FRAME_WIDTH, 3)
        if pixels.shape != expected_shape:
            raise RuntimeError(
                f"unexpected framebuffer shape {pixels.shape}; expected {expected_shape}"
            )
        return pixels.copy()

    def reset(self) -> None:
        """Start a fresh emulator process-equivalent episode.

        PyBoyAdvance has no public reset or save-state API.  Reconstructing the
        backend is therefore the only supported reset primitive in this phase.
        """

        self.release_all()
        from pyboy_advance import PyBoyAdvance as BackendPyBoyAdvance

        self._emulator = BackendPyBoyAdvance(
            rom=self._rom,
            bios=self._bios,
            skip_bios=self._skip_bios,
            emulation_speed=self._emulation_speed,
        )
        self._frame_count = 0

    def press(self, key: "GbaKey") -> None:
        """Press one GBA key through the backend."""

        self._emulator.press_key(_backend_key(key))

    def release(self, key: "GbaKey") -> None:
        """Release one GBA key through the backend."""

        self._emulator.release_key(_backend_key(key))

    def release_all(self) -> None:
        """Release every key, including after a failed input action."""

        for key in GbaKey:
            self.release(key)

    def tap(self, key: "GbaKey", hold_frames: int = 1, settle_frames: int = 1) -> None:
        """Press, hold, release, and settle one key deterministically."""

        _validate_frame_count(hold_frames, "hold_frames")
        _validate_frame_count(settle_frames, "settle_frames")
        self.press(key)
        try:
            self.frame(hold_frames)
        finally:
            self.release(key)
        self.frame(settle_frames)

    def peek_u8(self, address: int) -> int:
        """Read one byte through the backend's non-advancing public API."""

        return self._peek(address, 8)

    def peek_u16(self, address: int) -> int:
        """Read one little-endian unsigned 16-bit value without advancing time."""

        return self._peek(address, 16)

    def peek_u32(self, address: int) -> int:
        """Read one little-endian unsigned 32-bit value without advancing time."""

        return self._peek(address, 32)

    def _peek(self, address: int, width: int) -> int:
        reader = getattr(self._emulator, f"peek_u{width}", None)
        if reader is None:
            raise BackendCapabilityError(
                "installed PyBoy backend does not expose the required non-advancing "
                f"peek_u{width} telemetry API; install the SHA-pinned fork"
            )
        return int(reader(address))

    def capabilities(self) -> dict[str, bool]:
        """Report capabilities without pretending missing backend APIs exist."""

        return {
            "frames": callable(getattr(self._emulator, "frame", None)),
            "keys": callable(getattr(self._emulator, "press_key", None))
            and callable(getattr(self._emulator, "release_key", None)),
            "pixels": hasattr(self._emulator, "screen"),
            "read_telemetry": all(
                callable(getattr(self._emulator, name, None))
                for name in ("peek_u8", "peek_u16", "peek_u32")
            ),
            "timing_telemetry": callable(
                getattr(self._emulator, "timing_checkpoint", None)
            ),
        }

    def require_capabilities(self, *required: str) -> None:
        missing = [name for name in required if not self.capabilities().get(name, False)]
        if missing:
            raise BackendCapabilityError(
                "backend is missing required capabilities: " + ", ".join(missing)
            )

class GbaKey(Enum):
    """The ten physical buttons available on a GBA controller."""

    A = auto()
    B = auto()
    SELECT = auto()
    START = auto()
    RIGHT = auto()
    LEFT = auto()
    UP = auto()
    DOWN = auto()
    R = auto()
    L = auto()


def _validate_frame_count(value: int, name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an integer")
    if value < 0:
        raise ValueError(f"{name} must be non-negative")


def _backend_key(key: GbaKey) -> Any:
    if not isinstance(key, GbaKey):
        raise TypeError("key must be a GbaKey")
    try:
        from pyboy_advance.constants import Key
    except ImportError as exc:  # pragma: no cover - backend-dependent
        raise RuntimeError("PyBoy Advance key input is unavailable") from exc
    names = {
        GbaKey.A: "BUTTON_A",
        GbaKey.B: "BUTTON_B",
        GbaKey.SELECT: "BUTTON_SELECT",
        GbaKey.START: "BUTTON_START",
        GbaKey.RIGHT: "DPAD_RIGHT",
        GbaKey.LEFT: "DPAD_LEFT",
        GbaKey.UP: "DPAD_UP",
        GbaKey.DOWN: "DPAD_DOWN",
        GbaKey.R: "SHOULDER_RIGHT",
        GbaKey.L: "SHOULDER_LEFT",
    }
    return getattr(Key, names[key])

